var payload;
try {
	payload = JSON.parse(producer.entry_condition);
}catch(e) {
	payload = {};
}

if (typeof payload.query !== 'undefined') {
	// This record producer is orderable by any authenticated user, so the submitted
	// condition is untrusted input. A "javascript:" operand in an encoded query is
	// later inlined verbatim and evaluated un-sandboxed by GlideFilter, which would
	// hand an unprivileged submitter arbitrary server-side script execution.
	var condition = String(payload.query);
	if (condition.toLowerCase().indexOf('javascript:') !== -1) {
		gs.warn('[IAR Configuration] Rejected entry condition containing a "javascript:" operand, submitted by user: ' + gs.getUserName());
		gs.addErrorMessage(gs.getMessage('The entry condition contains an unsupported "javascript:" expression and was not saved.'));
	} else {
		current.setValue("condition", condition);
	}
}
